begin;
create function pg_temp.assert_true(value boolean,description text) returns void language plpgsql as $$
begin if value is distinct from true then raise exception 'Assertion failed: %',description; end if; end;
$$;
create function pg_temp.expect_error(statement text,expected text) returns void language plpgsql as $$
begin
  begin execute statement;
  exception when others then if position(expected in sqlerrm)>0 then return; end if; raise; end;
  raise exception 'Expected failure %',expected;
end;
$$;
insert into auth.users(id) values ('43000000-0000-4000-8000-000000000001'),('43000000-0000-4000-8000-000000000002'),('43000000-0000-4000-8000-000000000003');
select private.save_profile(id,jsonb_build_object('name','Managed Profile QA','occupation','','summary','Test','skills',array['Design'],'searching_skills','[]'::jsonb)) from auth.users where id::text like '43000000-%' and id::text not like '%003';
insert into private.memberships(user_id) values ('43000000-0000-4000-8000-000000000001'),('43000000-0000-4000-8000-000000000002');
insert into private.admin_roles(user_id,role) values ('43000000-0000-4000-8000-000000000001','admin');
create temp table fixture as select public.admin_prepare_create('43000000-0000-4000-8000-000000000001','43000000-0000-4000-8000-000000000004') id;
select pg_temp.assert_true((select id from fixture)=public.admin_prepare_create('43000000-0000-4000-8000-000000000001','43000000-0000-4000-8000-000000000004'),'Server reservation is stable on retry');
select pg_temp.expect_error($q$select public.admin_authorize_save('43000000-0000-4000-8000-000000000001','43000000-0000-4000-8000-000000000003',true,'43000000-0000-4000-8000-000000000004')$q$,'managed_profile_forbidden');
select pg_temp.expect_error($q$select public.admin_prepare_create('43000000-0000-4000-8000-000000000002','43000000-0000-4000-8000-000000000004')$q$,'admin_forbidden');
create temp table draft as select jsonb_build_object('name','Managed QA','occupation','','summary','Test managed profile','skills',array['Design'],'searching_skills','[]'::jsonb,'avatar_path',null) data;
select public.admin_save_profile('43000000-0000-4000-8000-000000000001',(select id from fixture),true,'43000000-0000-4000-8000-000000000004',(select data from draft));
select pg_temp.assert_true((select auth_user_id is null and profile_kind='managed' from public.profiles where id=(select id from fixture)),'Managed profile has no login identity');
select pg_temp.assert_true((public.admin_save_profile('43000000-0000-4000-8000-000000000001',(select id from fixture),true,'43000000-0000-4000-8000-000000000004',(select data from draft))->>'replayed')::boolean,'Create retry returns same result');
select pg_temp.assert_true((select count(*)=1 from private.admin_audit where actor_user_id='43000000-0000-4000-8000-000000000001'),'Create and audit commit once');
select pg_temp.expect_error($q$select public.admin_save_profile('43000000-0000-4000-8000-000000000001',(select id from fixture),true,'43000000-0000-4000-8000-000000000004',(select data || '{"name":"Changed"}'::jsonb from draft))$q$,'operation_id_conflict');
select pg_temp.assert_true((select count(*)=0 from public.connections where user_low=(select id from fixture) or user_high=(select id from fixture)),'Create never creates an audience or connection');
-- Edit, immutable photo version and optimistic concurrency.
create temp table before_edit as select updated_at from public.profiles where id=(select id from fixture);
insert into storage.objects(id,bucket_id,name,owner_id) select gen_random_uuid(),'avatars',id::text || '/' || repeat('a',64) || '.png',null from fixture;
update draft set data=data || jsonb_build_object('name','Managed edited QA','avatar_path',(select id::text || '/' || repeat('a',64) || '.png' from fixture));
select public.admin_save_profile('43000000-0000-4000-8000-000000000001',(select id from fixture),false,'43000000-0000-4000-8000-000000000010',(select data from draft),(select updated_at from before_edit));
select pg_temp.assert_true((select name='Managed edited QA' and avatar_path is not null from public.profiles where id=(select id from fixture)),'Edit saves the selected version');
select pg_temp.assert_true((select count(*)=2 from private.admin_audit where actor_user_id='43000000-0000-4000-8000-000000000001'),'Edit records actual actor and audit once');
select pg_temp.assert_true((public.admin_save_profile('43000000-0000-4000-8000-000000000001',(select id from fixture),false,'43000000-0000-4000-8000-000000000010',(select data from draft),(select updated_at from before_edit))->>'replayed')::boolean,'Edit retry returns original acknowledgement');
select pg_temp.expect_error($q$select public.admin_save_profile('43000000-0000-4000-8000-000000000001',(select id from fixture),false,'43000000-0000-4000-8000-000000000011',(select data from draft),(select updated_at from before_edit))$q$,'profile_version_conflict');
update private.managed_profile_grants set can_manage=false where profile_id=(select id from fixture);
select pg_temp.expect_error($q$select public.admin_set_profile_enabled('43000000-0000-4000-8000-000000000001',(select id from fixture),false,'43000000-0000-4000-8000-000000000012',clock_timestamp())$q$,'managed_profile_forbidden');
update private.managed_profile_grants set can_manage=true where profile_id=(select id from fixture);
-- Explicit local-only fixture, not a product command.
insert into public.connections(user_low,user_high) select least(id,'43000000-0000-4000-8000-000000000002'::uuid),greatest(id,'43000000-0000-4000-8000-000000000002'::uuid) from fixture;
create temp table thread as select gen_random_uuid() id;
insert into public.conversations(id,user_low,user_high) select t.id,least(f.id,'43000000-0000-4000-8000-000000000002'::uuid),greatest(f.id,'43000000-0000-4000-8000-000000000002'::uuid) from fixture f,thread t;
insert into public.conversation_members(conversation_id,user_id) select t.id,f.id from thread t,fixture f union all select id,'43000000-0000-4000-8000-000000000002' from thread;
grant select on fixture,thread to authenticated;
set local role authenticated;
select set_config('request.jwt.claim.sub','43000000-0000-4000-8000-000000000002',true);
select pg_temp.assert_true((select count(*)=1 from storage.objects where name=(select id::text || '/' || repeat('a',64) || '.png' from fixture)),'Active direct peer reads selected managed avatar');
reset role;
select public.chat_send('43000000-0000-4000-8000-000000000002',(select id from thread),'43000000-0000-4000-8000-000000000005','Before disable');
create temp table version as select updated_at from public.profiles where id=(select id from fixture);
select public.admin_set_profile_enabled('43000000-0000-4000-8000-000000000001',(select id from fixture),false,'43000000-0000-4000-8000-000000000006',(select updated_at from version));
select pg_temp.assert_true((public.admin_set_profile_enabled('43000000-0000-4000-8000-000000000001',(select id from fixture),false,'43000000-0000-4000-8000-000000000006',(select updated_at from version))->>'replayed')::boolean,'Disable retry is stable');
select pg_temp.assert_true(jsonb_array_length(public.member_network('43000000-0000-4000-8000-000000000002')->'contacts')=0,'Disabled excluded from active Contacts');
select pg_temp.assert_true((public.member_network('43000000-0000-4000-8000-000000000002')->'profile'->>'contact_count')::int=0,'Disabled excluded from count');
set local role authenticated;
select set_config('request.jwt.claim.sub','43000000-0000-4000-8000-000000000002',true);
select pg_temp.assert_true((select count(*)=0 from public.profiles where id=(select id from fixture)),'Disabled hidden by profile RLS');
select pg_temp.assert_true((select count(*)=0 from storage.objects where name=(select id::text || '/' || repeat('a',64) || '.png' from fixture)),'Disabled hidden from ordinary avatar reads');
reset role;
select pg_temp.expect_error($q$select public.chat_send('43000000-0000-4000-8000-000000000002',(select id from thread),'43000000-0000-4000-8000-000000000007','After disable')$q$,'conversation_forbidden');
select pg_temp.assert_true(jsonb_array_length(public.chat_history('43000000-0000-4000-8000-000000000002',(select id from thread))->'messages')=1,'Existing personal history survives');
select pg_temp.expect_error($q$select public.admin_set_profile_enabled('43000000-0000-4000-8000-000000000001',(select id from fixture),true,'43000000-0000-4000-8000-000000000008',(select updated_at from version))$q$,'profile_version_conflict');
select public.admin_set_profile_enabled('43000000-0000-4000-8000-000000000001',(select id from fixture),true,'43000000-0000-4000-8000-000000000008',(select updated_at from public.profiles where id=(select id from fixture)));
select pg_temp.assert_true(jsonb_array_length(public.member_network('43000000-0000-4000-8000-000000000002')->'contacts')=1,'Restore returns existing connection');
select pg_temp.assert_true((select count(*)=1 from public.messages where conversation_id=(select id from thread)),'History stays unchanged');
select pg_temp.expect_error($q$select public.admin_save_profile('43000000-0000-4000-8000-000000000001','43000000-0000-4000-8000-000000000002',false,'43000000-0000-4000-8000-000000000009',(select data from draft),clock_timestamp())$q$,'managed_profile_forbidden');
grant select on thread to authenticated;
set local role authenticated;
select set_config('request.jwt.claim.sub','43000000-0000-4000-8000-000000000002',true);
select pg_temp.assert_true((select count(*)=1 from public.messages where conversation_id=(select id from thread)),'Participant RLS preserves history');
select pg_temp.expect_error($q$select public.admin_prepare_create(auth.uid(),gen_random_uuid())$q$,'permission denied');
select pg_temp.expect_error($q$delete from public.profiles where id=auth.uid()$q$,'permission denied');
rollback;
